#include "face_probe.h"

// Generated by build.sh; defines OPENDUBS_PROBE_FACEDET only when the probe is requested.
#include "face_probe_config.h"

#ifndef OPENDUBS_PROBE_FACEDET

void faceProbeStart() {}   // deliberately empty -- see face_probe.h

#else

#include <esp_heap_caps.h>
#include <esp_timer.h>
#include <freertos/FreeRTOS.h>
#include <freertos/task.h>
#include <mooncake_log.h>

#include "dl_image.hpp"
#include "human_face_detect.hpp"

// Generated at build time by build.sh from probe/human_face.jpg, so it cannot drift from the
// committed fixture the way a checked-in generated file would. See build.sh sync_sources().
#include "face_probe_image.h"

namespace {

constexpr const char* kTag = "faceprobe";

// The reference image ships with esp-dl's own human_face_detect example, so it is the input the
// model was demonstrated against -- which is what makes a miss meaningful rather than arguable.
// 320x240. Expect exactly one face, roughly centred.
constexpr int kExpectFaces = 1;

// Enough passes to separate first-run cost (model load, PSRAM allocation, cache cold) from the
// steady state. The first number is the one that matters for a one-shot glance at a bystander;
// the steady state is the one that matters for tracking.
constexpr int kPasses = 8;

void report(HumanFaceDetect* det)
{
    // Decode once, outside the timed loop: we are measuring INFERENCE, and folding a software JPEG
    // decode into that number would quietly make the model look several times slower than it is.
    // (The P4 has a hardware JPEG codec. This probe does not use it -- the decode is not what is
    // being measured, and reaching for the accelerator here would add a variable, not remove one.)
    auto img = dl::image::sw_decode_jpeg(
        {(uint8_t*)kFaceProbeJpeg, sizeof(kFaceProbeJpeg)},
        dl::image::DL_IMAGE_PIX_TYPE_RGB888);

    if (!img.data) {
        mclog::tagError(kTag, "INCONCLUSIVE: jpeg decode failed -- the probe is broken, not the model");
        return;
    }
    mclog::tagInfo(kTag, "decoded {}x{} rgb888", img.width, img.height);

    int64_t first = 0, total = 0;
    size_t  faces = 0;

    for (int i = 0; i < kPasses; ++i) {
        const int64_t t0 = esp_timer_get_time();
        auto& results    = det->run(img);
        const int64_t dt = esp_timer_get_time() - t0;

        if (i == 0) {
            first = dt;
            faces = results.size();
            // Print the boxes once. A count alone cannot distinguish "found the face" from "found
            // a false positive somewhere else", and that distinction is the whole point of using a
            // reference image with a known answer.
            for (const auto& r : results) {
                mclog::tagInfo(kTag, "  face score={:.3f} box=({},{})-({},{})",
                               r.score, r.box[0], r.box[1], r.box[2], r.box[3]);
            }
        } else {
            total += dt;
        }
        vTaskDelay(pdMS_TO_TICKS(5));   // yield; this task must never starve the LVGL task
    }

    const float firstMs  = first / 1000.0f;
    const float steadyMs = (kPasses > 1) ? (total / (float)(kPasses - 1)) / 1000.0f : firstMs;

    mclog::tagInfo(kTag, "first={:.1f}ms steady={:.1f}ms ({:.1f} fps) faces={} expect={}",
                   firstMs, steadyMs, steadyMs > 0 ? 1000.0f / steadyMs : 0.0f,
                   (int)faces, kExpectFaces);
    mclog::tagInfo(kTag, "psram free={}K largest={}K",
                   heap_caps_get_free_size(MALLOC_CAP_SPIRAM) / 1024,
                   heap_caps_get_largest_free_block(MALLOC_CAP_SPIRAM) / 1024);

    // State the verdict. Do not make the reader infer it from numbers, and do not blame the
    // hardware for a result the probe cannot distinguish.
    if (faces == kExpectFaces) {
        mclog::tagInfo(kTag, "VERDICT: PASS -- detector works, {:.1f}ms per frame steady", steadyMs);
    } else if (faces == 0) {
        mclog::tagError(kTag, "VERDICT: FAIL -- no face in an image that contains one");
    } else {
        mclog::tagError(kTag, "VERDICT: FAIL -- {} faces in an image containing {}",
                        (int)faces, kExpectFaces);
    }

    heap_caps_free(img.data);
}

void task(void*)
{
    // Let the face app finish building its scene first. The probe is a guest here: it allocates
    // several MB of PSRAM for the model and must not race the eye's own allocation at startup.
    vTaskDelay(pdMS_TO_TICKS(4000));

    mclog::tagInfo(kTag, "constructing HumanFaceDetect (model load)");
    const int64_t t0  = esp_timer_get_time();
    auto*         det = new HumanFaceDetect();
    mclog::tagInfo(kTag, "model loaded in {:.0f}ms", (esp_timer_get_time() - t0) / 1000.0f);

    for (;;) {
        report(det);
        // Repeat, because attaching to the port resets nothing and a result printed once at boot is
        // a result nobody can read.
        vTaskDelay(pdMS_TO_TICKS(15000));
    }
}

}  // namespace

void faceProbeStart()
{
    // Its own task, at LOW priority, off the LVGL task. Inference takes tens of milliseconds and
    // running it inline would stall the render loop -- which would then look like the freezes we
    // spent several rounds chasing.
    //
    // STATIC, with both buffers forced INTERNAL. A plain xTaskCreate() here asserted:
    //
    //   assert failed: xTaskCreateStaticPinnedToCore (xPortCheckValidTCBMem(pxTaskBuffer))
    //
    // A FreeRTOS task control block MUST live in internal RAM, and this build has little left --
    // esp-dl's own allocations crowd it, and the vendor config permits task memory in external
    // RAM, so the allocator handed back PSRAM and the check fired. Allocating both the TCB and the
    // stack with MALLOC_CAP_INTERNAL says what is actually required instead of hoping.
    static StaticTask_t* tcb   = nullptr;
    static StackType_t*  stack = nullptr;
    constexpr uint32_t   kStackWords = 6144;

    tcb   = (StaticTask_t*)heap_caps_malloc(sizeof(StaticTask_t), MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
    stack = (StackType_t*)heap_caps_malloc(kStackWords * sizeof(StackType_t),
                                           MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
    if (!tcb || !stack) {
        // Say so, rather than asserting or silently doing nothing. If the probe cannot run, that
        // is itself the measurement: esp-dl does not leave room for another task on this build.
        mclog::tagError(kTag, "INCONCLUSIVE: no internal RAM for the probe task (free internal={}K)",
                        heap_caps_get_free_size(MALLOC_CAP_INTERNAL) / 1024);
        return;
    }
    xTaskCreateStatic(task, "faceprobe", kStackWords, nullptr, 2, stack, tcb);
}

#endif  // OPENDUBS_PROBE_FACEDET
